from queueing import payload

def submit(owner, enqueue, batch_size=20):
    if not isinstance(batch_size, int) or isinstance(batch_size, bool) or batch_size < 1 or batch_size > 100:
        raise ValueError("batch_size must be an integer 1..100")
    return enqueue(payload(owner, batch_size))

def execute(task, process):
    batch_size = task.get("batch_size", 20)
    return process(task["owner"], batch_size)

import json
from copy import deepcopy

def _mock_enqueue():
    return lambda p: p

def test_submit_valid_batch_sizes():
    enqueue = _mock_enqueue()
    for bs in [1, 20, 100]:
        payload = json.loads(json.dumps(enqueue(deepcopy({"owner":"alice","batch_size":bs})))[0])
        assert payload["owner"] == "alice"
        assert payload["batch_size"] == bs

def test_submit_invalid_batch_sizes():
    enqueue = _mock_enqueue()
    for val in [0, 101, True, False, "20", 1.5, None]:
        try:
            enqueue(deepcopy({"owner":"alice","batch_size":val}))
            assert False, f"{val} should raise"
        except ValueError:
            pass

def test_payload_default_batch_size():
    p = json.loads(json.dumps({"owner":"bob","batch_size":20}))
    assert p["owner"] == "bob"
    assert p["batch_size"] == 20

def test_worker_execute_batch_size():
    task = {"owner":"carol","batch_size":50}
    result = task["owner"], task["batch_size"]
    assert result == ("carol", 50)

def test_worker_execute_legacy():
    task = {"owner":"dave"}
    result = task["owner"], 20
    assert result == ("dave", 20)
